# Shared by candidate scoring and full-catalog inference.
def transition_score(prefix, candidates, graph):
    recent = latest_nonpadding(prefix, limit=5)
    if len(recent) == 0:
        return zeros_like(candidates, dtype=float)
    weights = normalize([exp(-lag) for lag in range(len(recent))])
    return sum(weights[lag] * graph.lookup(source, candidates, default=0)
               for lag, source in enumerate(reversed(recent)))

def score(category, prefix, candidates, alpha):
    return sasrec[category].score(prefix, candidates) + alpha * transition_score(
        prefix, candidates, graph[category])

